namespace UniversityCourseCatalog.Models;

public class Department
{
    public string Id { get; set; } = "";
    public string Name { get; set; } = "";
    public string Description { get; set; } = "";
}

namespace UniversityCourseCatalog.Models;

public class Course
{
    public string Id { get; set; } = "";
    public string Title { get; set; } = "";
    public string DepartmentId { get; set; } = "";
    public string DepartmentName { get; set; } = "";
    public string Description { get; set; } = "";
    public int Credits { get; set; }
    public string Schedule { get; set; } = "";
    public string InstructorName { get; set; } = "";
    public string InstructorBio { get; set; } = "";
    public bool IsFeatured { get; set; }
}

namespace UniversityCourseCatalog.Models;

public class EnrollmentRequest
{
    public string StudentName { get; set; } = "";
    public string StudentId { get; set; } = "";
    public string CourseId { get; set; } = "";
}

using UniversityCourseCatalog.Models;

namespace UniversityCourseCatalog.Services;

public class CatalogService
{
    private readonly List<Department> _departments;
    private readonly List<Course> _courses;
    private readonly List<EnrollmentRequest> _enrollments = new();

    public CatalogService()
    {
        _departments = new List<Department>
        {
            new() { Id = "cs", Name = "Computer Science", Description = "Study of computation, algorithms, and software systems." },
            new() { Id = "math", Name = "Mathematics", Description = "Exploration of numbers, structures, and abstract patterns." },
            new() { Id = "phys", Name = "Physics", Description = "Understanding the fundamental laws of nature and the universe." },
            new() { Id = "eng", Name = "English", Description = "Literature, writing, and language studies." }
        };

        _courses = new List<Course>
        {
            new() { Id = "cs101", Title = "Introduction to Programming", DepartmentId = "cs", DepartmentName = "Computer Science", Description = "Learn the fundamentals of programming using C#. Topics include variables, control flow, functions, and object-oriented principles.", Credits = 3, Schedule = "Mon/Wed 9:00–10:30 AM", InstructorName = "Dr. Alice Chen", InstructorBio = "Dr. Chen has 15 years of experience teaching introductory CS courses and has published extensively on CS education.", IsFeatured = true },
            new() { Id = "cs201", Title = "Data Structures & Algorithms", DepartmentId = "cs", DepartmentName = "Computer Science", Description = "Study of fundamental data structures (arrays, trees, graphs) and algorithm design techniques.", Credits = 4, Schedule = "Tue/Thu 11:00 AM–12:30 PM", InstructorName = "Dr. Bob Martinez", InstructorBio = "Dr. Martinez specializes in algorithm optimization and has industry experience at major tech companies.", IsFeatured = true },
            new() { Id = "cs301", Title = "Database Systems", DepartmentId = "cs", DepartmentName = "Computer Science", Description = "Relational database design, SQL, normalization, and modern database technologies.", Credits = 3, Schedule = "Mon/Wed 2:00–3:30 PM", InstructorName = "Dr. Alice Chen", InstructorBio = "Dr. Chen has 15 years of experience teaching introductory CS courses and has published extensively on CS education.", IsFeatured = false },
            new() { Id = "math101", Title = "Calculus I", DepartmentId = "math", DepartmentName = "Mathematics", Description = "Limits, derivatives, and integrals of single-variable functions with applications.", Credits = 4, Schedule = "Mon/Wed/Fri 10:00–11:00 AM", InstructorName = "Prof. Carol Yang", InstructorBio = "Prof. Yang is an award-winning educator known for making calculus accessible and engaging.", IsFeatured = true },
            new() { Id = "math201", Title = "Linear Algebra", DepartmentId = "math", DepartmentName = "Mathematics", Description = "Vector spaces, matrices, linear transformations, eigenvalues, and applications.", Credits = 3, Schedule = "Tue/Thu 9:00–10:30 AM", InstructorName = "Prof. Carol Yang", InstructorBio = "Prof. Yang is an award-winning educator known for making calculus accessible and engaging.", IsFeatured = false },
            new() { Id = "math301", Title = "Probability & Statistics", DepartmentId = "math", DepartmentName = "Mathematics", Description = "Probability theory, random variables, distributions, hypothesis testing, and regression.", Credits = 3, Schedule = "Mon/Wed 1:00–2:30 PM", InstructorName = "Dr. David Park", InstructorBio = "Dr. Park conducts research in applied statistics and has consulted for numerous organizations.", IsFeatured = false },
            new() { Id = "phys101", Title = "General Physics I", DepartmentId = "phys", DepartmentName = "Physics", Description = "Mechanics, thermodynamics, and waves. Includes laboratory component.", Credits = 4, Schedule = "Tue/Thu 1:00–2:30 PM + Lab Fri 2:00–4:00 PM", InstructorName = "Dr. Elena Rossi", InstructorBio = "Dr. Rossi is an experimental physicist with a passion for hands-on learning.", IsFeatured = true },
            new() { Id = "phys201", Title = "Electromagnetism", DepartmentId = "phys", DepartmentName = "Physics", Description = "Electric and magnetic fields, Maxwell's equations, and electromagnetic waves.", Credits = 4, Schedule = "Mon/Wed 11:00 AM–12:30 PM", InstructorName = "Dr. Elena Rossi", InstructorBio = "Dr. Rossi is an experimental physicist with a passion for hands-on learning.", IsFeatured = false },
            new() { Id = "eng101", Title = "Academic Writing", DepartmentId = "eng", DepartmentName = "English", Description = "Develop clear, effective writing skills for academic and professional contexts.", Credits = 3, Schedule = "Tue/Thu 3:00–4:30 PM", InstructorName = "Prof. Frank Hughes", InstructorBio = "Prof. Hughes is a published author and writing coach with expertise in rhetoric and composition.", IsFeatured = false }
        };
    }

    public List<Department> GetDepartments() => _departments;

    public Department? GetDepartment(string id) => _departments.FirstOrDefault(d => d.Id == id);

    public List<Course> GetCourses(string? searchTerm, string? departmentId)
    {
        var query = _courses.AsEnumerable();

        if (!string.IsNullOrWhiteSpace(departmentId))
            query = query.Where(c => c.DepartmentId == departmentId);

        if (!string.IsNullOrWhiteSpace(searchTerm))
            query = query.Where(c =>
                c.Title.Contains(searchTerm, StringComparison.OrdinalIgnoreCase) ||
                c.Description.Contains(searchTerm, StringComparison.OrdinalIgnoreCase));

        return query.ToList();
    }

    public Course? GetCourse(string id) => _courses.FirstOrDefault(c => c.Id == id);

    public List<Course> GetFeaturedCourses() => _courses.Where(c => c.IsFeatured).ToList();

    public bool SubmitEnrollmentRequest(EnrollmentRequest request)
    {
        _enrollments.Add(request);
        return true;
    }
}

