@page "/"
@inject CatalogService Catalog

<PageTitle>Home - University Course Catalog</PageTitle>

<h1>Welcome to the University Course Catalog</h1>
<p>Browse our departments, explore courses, and enroll today.</p>

<h2>Featured Courses</h2>
<div class="card-grid">
    @foreach (var course in Catalog.GetFeaturedCourses())
    {
        <div class="card">
            <h3><a href="/courses/@course.Id">@course.Title</a></h3>
            <p class="card-meta">@course.DepartmentName · @course.Credits credits</p>
            <p>@course.Description</p>
        </div>
    }
</div>

<h2>Departments</h2>
<ul class="department-list">
    @foreach (var dept in Catalog.GetDepartments())
    {
        <li><a href="/courses?DepartmentId=@dept.Id">@dept.Name</a> — @dept.Description</li>
    }
</ul>
