@page "/courses"
@inject CatalogService Catalog

<PageTitle>Courses - University Course Catalog</PageTitle>

<h1>Course Catalog</h1>

<form method="get" action="/courses" class="search-form">
    <input type="text" name="Search" value="@Search" placeholder="Search courses..." />
    <select name="DepartmentId">
        <option value="">All Departments</option>
        @foreach (var dept in Catalog.GetDepartments())
        {
            <option value="@dept.Id" selected="@(dept.Id == DepartmentId)">@dept.Name</option>
        }
    </select>
    <button type="submit">Search</button>
</form>

@{
    var courses = Catalog.GetCourses(Search, DepartmentId);
}

@if (courses.Count == 0)
{
    <p>No courses found matching your criteria.</p>
}
else
{
    <div class="course-list">
        @foreach (var course in courses)
        {
            <div class="course-item">
                <h3><a href="/courses/@course.Id">@course.Title</a></h3>
                <p class="card-meta">@course.DepartmentName · @course.Credits credits · @course.Schedule</p>
                <p>@course.Description</p>
            </div>
        }
    </div>
